struct reqcontext {
	uint64_t seq;
	uint64_t origcookie;
	struct nbd_request req;
	struct reqcontext *next;
	struct reqcontext *prev;
};

struct rclist {
	struct reqcontext *head;
	struct reqcontext *tail;
	int numitems;
};

struct chunk {
	char *buffer;
	char *readptr;
	char *writeptr;
	uint64_t space;
	uint64_t length;
	struct chunk *next;
	struct chunk *prev;
};

struct chunklist {
	struct chunk *head;
	struct chunk *tail;
	int numitems;
};

struct blkitem {
