void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t block = pos / TREEPAGESIZE;
	off_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	int levels = 1;
	off_t capacity = TREEDIRSIZE;
	int idx[...];

	while (capacity < blocks) {
		levels++;
		capacity *= TREEDIRSIZE;
	}

	if (ppos)
		*ppos = pos % TREEPAGESIZE;

	size_t len = strlen(name);
	for (int level = levels - 1; level >= 1; level--) {
		off_t divisor = 1;
		for (int j = 0; j < level; j++)
			divisor *= TREEDIRSIZE;
		int written = snprintf(name + len, lenmax - len, "/TREE%04d", (int)((block / divisor) % TREEDIRSIZE));
		if (written < 0 || written >= lenmax - len) {
			name[0] = '\0';
			return;
		}
		len += written;
	}
	int written = snprintf(name + len, lenmax - len, "/FILE%04d", (int)(block % TREEDIRSIZE));
	if (written < 0 || written >= lenmax - len)
		name[0] = '\0';
}
