arguments.content:
/*
 * Tree files support
 *
 * An export in treefiles mode keeps its data in a tree of small block
 * files below the directory named by the export name. Every block file
 * holds TREEPAGESIZE bytes of export data, and every directory holds at
 * most TREEDIRSIZE entries, so the nesting depth grows with the size of
 * the export: one level of FILEXXXX files for exports of up to
 * TREEDIRSIZE blocks, an extra level of TREEXXXX directories per
 * additional factor TREEDIRSIZE in export size.
 *
 * The block file holding the data at export offset 'pos' is named after
 * the number of the TREEPAGESIZE-sized block containing 'pos', split
 * into base-TREEDIRSIZE digits: the most significant digits name the
 * chain of TREEXXXX directories, the least significant digit names the
 * FILEXXXX file.
 */

#include "config.h"
#include "nbd-debug.h"

#include <nbdsrv.h>

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdio.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#include "treefiles.h"

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/**
 * Compute the number of directory levels needed to store an export of
 * the given size.
 *
 * @param size the size of the export
 * @return the number of levels; 1 means the block files live directly
 * below the root directory of the export
 **/
static int tree_levels(off_t size) {
	off_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	int levels = 1;
	off_t capacity = TREEDIRSIZE;

	while (capacity < blocks) {
		levels++;
		capacity *= TREEDIRSIZE;
	}

	return levels;
}

/**
 * Construct the path of the block file holding the data at a given
 * offset of the export.
 *
 * @param name the path of the root directory of the export on input;
 * the full path of the block file on output. If the buffer is too
 * small, an empty string is returned in name.
 * @param lenmax the size of the buffer name points at
 * @param size the size of the export
 * @param pos the offset into the export
 * @param ppos [out] offset into the block file where the data at pos
 * is stored
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t block = pos / TREEPAGESIZE;
	int levels = tree_levels(size);
	size_t len;
	int level;

	if (ppos)
		*ppos = pos % TREEPAGESIZE;

	len = strlen(name);
	for (level = levels - 1; level >= 1; level--) {
		off_t divisor = 1;
		int written;
		int i;

		for (i = 0; i < level; i++)
			divisor *= TREEDIRSIZE;

		if (len >= (size_t)lenmax)
			goto truncated;
		written = snprintf(name + len, lenmax - len, "/TREE%04d",
				   (int)((block / divisor) % TREEDIRSIZE));
		if (written < 0 || written >= lenmax - (int)len)
			goto truncated;
		len += written;
	}

	if (len >= (size_t)lenmax)
		goto truncated;
	if (snprintf(name + len, lenmax - len, "/FILE%04d",
		     (int)(block % TREEDIRSIZE)) >= lenmax - (int)len)
		goto truncated;
	return;

truncated:
	DEBUG("Path for treefile at offset %llu too long\n", (unsigned long long)pos);
	name[0] = '\0';
}

/**
 * Create a directory, if it does not exist yet.
 *
 * @param path the directory to create
 **/
void mkdir_path(char *path) {
	if (mkdir(path, 0700) == -1 && errno != EEXIST) {
		msg(LOG_ERR, "Could not create directory %s: %s",
		    path, strerror(errno));
	}
}

/**
 * Open the block file holding the data at a given offset of the export.
 *
 * @param name the path of the root directory of the export on input;
 * the full path of the block file on output. The buffer must be at
 * least PATH_MAX bytes long.
 * @param mode the mode with which to open the file; if it includes
 * O_CREAT, the directories leading to the block file are created as
 * needed
 * @param size the size of the export
 * @param pos the offset into the export
 * @param mutex serializes path construction and directory creation
 * @return a file descriptor for the block file, or -1 on error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	off_t ppos;
	size_t rootlen;
	int fd;

	pthread_mutex_lock(mutex);
	rootlen = strlen(name);
	construct_path(name, PATH_MAX, size, pos, &ppos);
	if (name[0] != '\0' && (mode & O_CREAT)) {
		char *p;

		for (p = name + rootlen + 1; *p; p++) {
			if (*p == '/') {
				*p = '\0';
				mkdir_path(name);
				*p = '/';
			}
		}
	}
	fd = name[0] == '\0' ? -1 : open(name, mode, 0600);
	if (fd == -1 && name[0] == '\0')
		errno = ENAMETOOLONG;
	pthread_mutex_unlock(mutex);

	return fd;
}

/**
 * Delete the block file holding the data at a given offset of the
 * export, e.g. because the block has been trimmed.
 *
 * @param name the path of the root directory of the export; the buffer
 * must be at least PATH_MAX bytes long and is overwritten with the full
 * path of the block file
 * @param size the size of the export
 * @param pos the offset into the export
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	construct_path(name, PATH_MAX, size, pos, NULL);
	if (name[0] == '\0')
		return;
	if (unlink(name) == -1 && errno != ENOENT) {
		msg(LOG_ERR, "Could not delete treefile %s: %s",
		    name, strerror(errno));
	}
}

