#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/**
 * Process a TRIM request against a treefiles export: block files fully
 * covered by the trimmed range are deleted, partially covered ones get
 * a hole punched in them.
 */
static int trim_treefiles(struct nbd_request* req, CLIENT* client) {
	char path[PATH_MAX];
	off_t from = req->from;
	off_t end = req->from + req->len;

	while (from < end) {
		off_t blockstart = from - (from % TREEPAGESIZE);
		off_t blockend = blockstart + TREEPAGESIZE;
		off_t chunkend;

		if (blockend > (off_t)client->exportsize)
			blockend = client->exportsize;
		chunkend = end < blockend ? end : blockend;

		strncpy(path, client->exportname, sizeof(path));
		path[sizeof(path)-1] = '\0';
		if (from == blockstart && chunkend == blockend) {
			/* The whole block is unused now, delete it */
			delete_treefile(path, client->exportsize, blockstart);
		} else {
			int fd = open_treefile(path, O_RDONLY, client->exportsize, blockstart, &client->treelock);
			if (fd >= 0) {
				punch_hole(fd, from - blockstart, chunkend - from);
				close(fd);
			}
		}
		from = chunkend;
	}
	DEBUG("Performed TRIM request on treefiles from %llu to %llu", (unsigned long long) req->from, (unsigned long long) req->len);
	return 0;
}
```

